        for k,lo,hi in [('duration',5,480),('buffer',0,120),('price',0,100000000),('deposit_percent',1,100),('percent',1,99)]:
            if k in row:row[k]=integer(row[k],lo,hi,k)
        if entity=='staff':
            for key in ('service_ids','hours'):
