CREATE TABLE [services] (
    [Id] INT IDENTITY(1,1) NOT NULL PRIMARY KEY,
    [name] NVARCHAR(MAX) NOT NULL,
    [category] NVARCHAR(MAX) NOT NULL DEFAULT ('Wellness'),
    [description] NVARCHAR(MAX) NOT NULL DEFAULT (''),
    [duration] BIGINT NOT NULL,
